const headers = $json.headers || {};
const query = $json.query || {};

const initData =
  headers["x-telegram-init-data"] ||
  headers["X-Telegram-Init-Data"] ||
  query.initData ||
  query.init_data ||
  null;

const transactionId = String(query.id || "").trim();
if (!/^\d+$/.test(transactionId)) {
  throw new Error("TRANSACTION_ID_INVALID");
}

return [{
  json: {
    initData,
    transaction_id: transactionId
  }
}];

const crypto = require("crypto");

const initData = $json.initData;
if (!initData) throw new Error("INIT_DATA_MISSING");

const botToken = $env.MONEYTRACK_BOT_TOKEN;
if (!botToken) throw new Error("BOT_TOKEN_MISSING");

function parseInitData(value) {
  const result = {};
  for (const part of value.split("&")) {
    const eqIndex = part.indexOf("=");
    if (eqIndex === -1) continue;
    result[decodeURIComponent(part.slice(0, eqIndex))] =
      decodeURIComponent(part.slice(eqIndex + 1));
  }
  return result;
}

const params = parseInitData(initData);
const receivedHash = params.hash;
if (!receivedHash) throw new Error("HASH_MISSING");
delete params.hash;

const dataCheckString = Object.keys(params)
  .sort()
  .map((key) => `${key}=${params[key]}`)
  .join("\n");

const secretKey = crypto
  .createHmac("sha256", "WebAppData")
  .update(botToken)
  .digest();

const calculatedHash = crypto
  .createHmac("sha256", secretKey)
  .update(dataCheckString)
  .digest("hex");

if (calculatedHash !== receivedHash) {
  throw new Error("INVALID_INIT_DATA_HASH");
}

const user = JSON.parse(params.user);
return [{
  json: {
    telegram_user_id: user.id,
    transaction_id: $json.transaction_id
  }
}];

const row = $input.first().json || {};
if (!row.user_found) throw new Error("USER_NOT_FOUND");
if (!row.deleted) throw new Error("TRANSACTION_NOT_FOUND");

return [{
  json: {
    data: {
      deleted: true,
      transaction: {
        id: row.id,
        description: row.description,
        amount_original: Number(row.amount_original || 0),
        currency_original: row.currency_original,
        transaction_date: row.transaction_date
      }
    }
  }
}];
